package viewer

import (
	"fmt"
	"testing"

	"github.com/alecthomas/chroma/v2/lexers"
)

func probe(t *testing.T, name, src string) {
	t.Helper()
	lx := lexers.Get(name)
	if lx == nil {
		t.Fatalf("no lexer %q", name)
	}
	it, err := lx.Tokenise(nil, src)
	if err != nil {
		t.Fatal(err)
	}
	fmt.Printf("=== %s ===\n", name)
	for _, tok := range it.Tokens() {
		fmt.Printf("%-24s %q\n", tok.Type, tok.Value)
	}
}

func TestProbeMarkdown(t *testing.T) {
	probe(t, "markdown", "# Title\n\n## Sub\n\nSome **bold** and *emph* and ~~gone~~ text.\n\n- item one\n- item two\n\n1. first\n\n> quoted\n\nInline `code` here.\n\n[link](http://x.y)\n\n```go\nfunc main() {}\n```\n\n---\n")
}

func TestProbeDocker(t *testing.T) {
	probe(t, "docker", "# comment\nFROM alpine:3.19 AS build\nRUN apk add --no-cache git\nENV FOO=bar\nCOPY . /app\nCMD [\"sh\"]\n")
}

func TestProbeBash(t *testing.T) {
	probe(t, "bash", "#!/usr/bin/env bash\nset -euo pipefail\n# a comment\nNAME=\"world\"\nif [ -n \"$NAME\" ]; then\n  echo \"hello ${NAME}\" | tr a-z A-Z\nfi\n")
}
EOF
